using System;using System.Drawing;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;
namespace Synkoz {
public sealed partial class Track {public bool CollapsedR9,PreviewOffR9;}
public sealed partial class CapturePanel {
void WirePreviewR9(PictureBox image,Track t){var timer=new Timer{Interval=SystemInformation.DoubleClickTime};timer.Tick+=async delegate{timer.Stop();t.PreviewOffR9=!t.PreviewOffR9;if(t.PreviewOffR9){var c=previews.FirstOrDefault(v=>v.Track==t);if(c!=null&&!Busy&&!paused){previews.Remove(c);await Task.Run(()=>Engine.Stop(c));c.Clear();}if(image.Image!=null){image.Image.Dispose();image.Image=null;}image.BackColor=Color.DimGray;}else await StartPreviews();};image.MouseClick+=delegate(object s,MouseEventArgs e){if(e.Button==MouseButtons.Left&&t.Video!=null)timer.Start();};image.MouseDoubleClick+=async delegate(object s,MouseEventArgs e){if(e.Button!=MouseButtons.Left)return;timer.Stop();t.PreviewOffR9=false;Expand(t);await StartPreviews();};image.Disposed+=delegate{timer.Dispose();};image.Paint+=delegate(object sender,PaintEventArgs e){if(t.PreviewOffR9)TextRenderer.DrawText(e.Graphics,"Aperçu\narrêté",image.Font,image.ClientRectangle,Color.White,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);};tips.SetToolTip(image,"Clic : aperçu on/off · Double clic : agrandir");}
void DecorateRowR9(TableLayoutPanel row,Track t,Panel setup,PictureBox image){var nav=new FlowLayoutPanel{Dock=DockStyle.Top,Height=25,WrapContents=false};foreach(var text in new[]{t.CollapsedR9?"▸":"▾","↑","↓"}){var action=text;var b=new Button{Text=text,Width=26,Height=24,ForeColor=Color.White,BackColor=Color.FromArgb(45,51,65),FlatStyle=FlatStyle.Flat};b.Click+=async delegate{if(Busy||paused)return;await StopPreviews();if(action=="↑"||action=="↓"){int at=tracks.IndexOf(t),to=at+(action=="↑"?-1:1);if(to>=0&&to<tracks.Count){tracks.RemoveAt(at);tracks.Insert(to,t);}}else t.CollapsedR9=!t.CollapsedR9;Render();await StartPreviews();};nav.Controls.Add(b);}var name=row.GetControlFromPosition(2,0);namesR10[t]=name;row.Controls.Remove(name);var title=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,Margin=Padding.Empty};title.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,104));title.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));title.RowStyles.Add(new RowStyle(SizeType.Percent,100));nav.Dock=DockStyle.None;nav.Width=100;nav.Height=30;title.Controls.Add(nav,0,0);title.Controls.Add(name,1,0);row.Controls.Add(title,2,0);if(t.CollapsedR9){setup.Visible=false;image.Visible=false;foreach(Control c in row.Controls)if(row.GetRow(c)==1)c.Visible=false;}else {foreach(Control c in row.Controls)if(c is Button&&c.Text=="Abandonner"){c.Dock=DockStyle.None;c.Width=80;c.Height=26;c.ForeColor=Color.WhiteSmoke;}}}
}}
